public int solve(int[] A) {
    int N = A.length;
    int[] prefix = new int[N];
    int[] suffix = new int[N];
    prefix[0] = A[0];
    for (int i = 1; i < N; i++) {
        prefix[i] = gcd(prefix[i - 1], A[i]);
    }
    suffix[N - 1] = A[N - 1];
    for (int i = N - 2; i >= 0; i--) {
        suffix[i] = gcd(suffix[i + 1], A[i]);
    }
    int best = 0;
    for (int i = 0; i < N; i++) {
        int cur;
        if (i == 0) {
            cur = suffix[1];
        } else if (i == N - 1) {
            cur = prefix[N - 2];
        } else {
            cur = gcd(prefix[i - 1], suffix[i + 1]);
        }
        best = Math.max(best, cur);
    }
    return best;
}
